    "courseBranch": "course/build-your-own-pi",
    "commit": "40e113d528d8a95905482311c06c1c4851167dc2",
    "parentCommit": "970bb071ab15e40e1521089013bbd40acefbc05b",
    "commitSubject": "add progressive resources and trusted extensions",
